import React, { useState } from 'react';

export default function App() {
  // Estados para cálculos
  const [valorPrincipal, setValorPrincipal] = useState(0);
  const [porcentagem, setPorcentagem] = useState(20);
  
  // Estados para Prazos
  const [dataIntimacao, setDataIntimacao] = useState('');
  const [prazoDias, setPrazoDias] = useState(15);

  // Estados para Checklist de Documentos
  const [docs, setDocs] = useState({
    procuracao: false,
    identidade: false,
    residencia: false,
    custas: false
  });

  // Cálculos Automáticos
  const valorHonorarios = (valorPrincipal * porcentagem) / 100;

  const calcularVencimento = () => {
    if (!dataIntimacao) return '---';
    let data = new Date(dataIntimacao + 'T00:00:00');
    let cont = 0;
    while (cont < prazoDias) {
      data.setDate(data.getDate() + 1);
      if (data.getDay() !== 0 && data.getDay() !== 6) cont++;
    }
    return data.toLocaleDateString('pt-BR');
  };

  const shareWhatsApp = () => {
    const msg = `*RESUMO JURÍDICO PRO*%0A` +
                `--------------------------%0A` +
                `💰 *Honorários:* R$ ${valorHonorarios.toLocaleString('pt-BR')}%0A` +
                `📅 *Prazo:* Vence em ${calcularVencimento()}%0A` +
                `--------------------------%0A` +
                `Gerado por Advogado Já ⚖️`;
    window.open(`https://wa.me/?text=${msg}`);
  };

  return (
    <div style={{ backgroundColor: '#f4f7f6', minHeight: '100vh', fontFamily: 'Arial, sans-serif' }}>
      {/* Header Estilizado */}
      <div style={{ backgroundColor: '#1e293b', color: 'white', padding: '20px', textAlign: 'center', boxShadow: '0 2px 10px rgba(0,0,0,0.2)' }}>
        <h1 style={{ margin: 0, fontSize: '24px' }}>⚖️ Advogado Já Pro</h1>
        <p style={{ margin: '5px 0 0', fontSize: '14px', opacity: 0.8 }}>Gestão e Cálculos em um clique</p>
      </div>

      <div style={{ maxWidth: '500px', margin: '0 auto', padding: '20px' }}>
        
        {/* Bloco 1: Financeiro */}
        <div style={cardStyle}>
          <h3 style={titleStyle}>💰 Calculadora de Honorários</h3>
          <p style={labelStyle}>Valor da Causa / Acordo (R$)</p>
          <input type="number" style={inputStyle} onChange={(e) => setValorPrincipal(e.target.value)} placeholder="0,00" />
          
          <p style={labelStyle}>Porcentagem (%)</p>
          <input type="number" value={porcentagem} style={inputStyle} onChange={(e) => setPorcentagem(e.target.value)} />
          
          <div style={resultStyle}>
            Valor Estimado: <br/>
            <strong style={{fontSize: '22px'}}>R$ {valorHonorarios.toLocaleString('pt-BR', {minimumFractionDigits: 2})}</strong>
          </div>
        </div>

        {/* Bloco 2: Prazos Processuais */}
        <div style={cardStyle}>
          <h3 style={titleStyle}>📅 Contador de Prazos (CPC)</h3>
          <p style={labelStyle}>Data da Intimação / Ciência</p>
          <input type="date" style={inputStyle} onChange={(e) => setDataIntimacao(e.target.value)} />
          
          <p style={labelStyle}>Tipo de Prazo</p>
          <select style={inputStyle} onChange={(e) => setPrazoDias(Number(e.target.value))} value={prazoDias}>
            <option value="5">Embargos (5 dias úteis)</option>
            <option value="15">Contestação/Recurso (15 dias úteis)</option>
            <option value="30">Prazo Especial (30 dias úteis)</option>
          </select>

          <div style={{ ...resultStyle, backgroundColor: '#fff5f5', color: '#c53030', border: '1px solid #feb2b2' }}>
            Vencimento Final: <br/>
            <strong style={{fontSize: '22px'}}>{calcularVencimento()}</strong>
          </div>
        </div>

        {/* Bloco 3: Checklist de Documentos */}
        <div style={cardStyle}>
          <h3 style={titleStyle}>📋 Checklist de Protocolo</h3>
          <div style={{ textAlign: 'left' }}>
            {Object.keys(docs).map(item => (
              <label key={item} style={{ display: 'block', padding: '8px 0', borderBottom: '1px solid #eee', cursor: 'pointer' }}>
                <input 
                  type="checkbox" 
                  checked={docs[item]} 
                  onChange={() => setDocs({...docs, [item]: !docs[item]})}
                  style={{ marginRight: '10px' }}
                />
                {item.charAt(0).toUpperCase() + item.slice(1)}
              </label>
            ))}
          </div>
        </div>

        {/* Ações Rápidas */}
        <button onClick={shareWhatsApp} style={mainButtonStyle}>
          📱 ENVIAR RESUMO PARA O WHATSAPP
        </button>
        
        <button onClick={() => window.print()} style={{ ...mainButtonStyle, backgroundColor: '#64748b', marginTop: '10px' }}>
          🖨️ IMPRIMIR FICHA DO CLIENTE
        </button>

      </div>
    </div>
  );
}

// Estilos em Objetos para facilitar
const cardStyle = { backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)', marginBottom: '20px', textAlign: 'center' };
const titleStyle = { margin: '0 0 15px', fontSize: '18px', color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' };
const labelStyle = { margin: '10px 0 5px', fontSize: '13px', color: '#64748b', textAlign: 'left' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', boxSizing: 'border-box', fontSize: '16px' };
const resultStyle = { marginTop: '15px', padding: '15px', backgroundColor: '#f0fdf4', borderRadius: '8px', color: '#166534' };
const mainButtonStyle = { width: '100%', padding: '16px', backgroundColor: '#22c55e', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' };
